207	impl AsyncRunner {
208	    /// Creates a new [`AsyncRunner`] instance.
209	    ///
210	    /// Creates channels but does not bind senders to thread-local storage.
211	    /// Call [`bind_senders`](Self::bind_senders) before creating clients that
212	    /// read from TLS, and again before entering the event loop.
213	    #[must_use]
214	    pub fn new() -> Self {
215	        use tokio::sync::mpsc::unbounded_channel; // tokio-import-ok
216	
217	        let (time_evt_tx, time_evt_rx) = unbounded_channel::<TimeEventHandler>();
218	        let (signal_tx, signal_rx) = unbounded_channel::<()>();
219	        let (exec_cmd_tx, exec_cmd_rx) = unbounded_channel::<TradingCommand>();
220	        let (exec_evt_tx, exec_evt_rx) = unbounded_channel::<ExecutionEvent>();
221	        let (data_cmd_tx, data_cmd_rx) = unbounded_channel::<DataCommand>();
222	        let (data_evt_tx, data_evt_rx) = unbounded_channel::<DataEvent>();
223	
224	        Self {
225	            channels: AsyncRunnerChannels {
226	                time_evt_rx,
227	                exec_evt_rx,
228	                exec_cmd_rx,
229	                data_evt_rx,
230	                data_cmd_rx,
231	            },
232	            time_evt_tx,
233	            signal_rx,
234	            signal_tx,
235	            exec_cmd_tx,
236	            exec_evt_tx,
237	            data_cmd_tx,
238	            data_evt_tx,
239	        }
240	    }
241	
242	    /// Binds this runner's channel senders to thread-local storage.
243	    ///
244	    /// Call before creating clients that read from TLS (e.g., in the builder),
245	    /// and again before entering the event loop to reclaim ownership if another
246	    /// runner was constructed on this thread in the interim.
247	    pub fn bind_senders(&self) {
248	        replace_time_event_sender(Arc::new(AsyncTimeEventSender::new(
