285	    /// Flushes all pending data events and commands from the channels.
286	    ///
287	    /// Loops until both data channels are empty, processing each item
288	    /// into the cache immediately. Used in `start()` where channels are
289	    /// not extracted.
290	    pub fn flush_pending_data(&mut self) {
291	        let mut total = 0;
292	
293	        loop {
294	            let mut progressed = false;
295	
296	            // Events drain before commands here even though the runtime select
297	            // prefers the opposite for everything-else: `LiveNode::start()`
298	            // calls this after `connect_data_clients()` to push queued
299	            // `DataEvent::Instrument` items into the cache. A pending
300	            // subscription command (e.g. `SubscribeBars`) processed before the
301	            // matching instrument lands would be rejected by the data engine.
302	            while let Ok(evt) = self.channels.data_evt_rx.try_recv() {
303	                Self::handle_data_event(evt);
304	                progressed = true;
305	                total += 1;
306	            }
307	
308	            while let Ok(cmd) = self.channels.data_cmd_rx.try_recv() {
309	                Self::handle_data_command(cmd);
310	                progressed = true;
311	                total += 1;
312	            }
313	
314	            if !progressed {
315	                break;
316	            }
317	        }
318	
319	        if total > 0 {
320	            log::debug!("Flushed {total} pending data events/commands");
321	        }
322	    }
