324	    /// Runs the async runner event loop.
325	    ///
326	    /// This method processes data events, time events, execution events, and signal events in an async loop.
327	    /// It will run until a signal is received or the event streams are closed.
328	    pub async fn run(&mut self) {
329	        self.bind_senders();
330	
331	        log::info!("AsyncRunner starting");
332	
333	        loop {
334	            tokio::select! {
335	                biased;
336	
337	                Some(()) = self.signal_rx.recv() => {
338	                    log::info!("AsyncRunner received signal, shutting down");
339	                    return;
340	                },
341	                Some(handler) = self.channels.time_evt_rx.recv() => {
342	                    Self::handle_time_event(handler);
343	                },
344	                Some(cmd) = self.channels.exec_cmd_rx.recv() => {
345	                    Self::handle_exec_command(cmd);
346	                },
347	                Some(evt) = self.channels.exec_evt_rx.recv() => {
348	                    Self::handle_exec_event(evt);
349	                },
350	                Some(cmd) = self.channels.data_cmd_rx.recv() => {
351	                    Self::handle_data_command(cmd);
352	                },
353	                Some(evt) = self.channels.data_evt_rx.recv() => {
354	                    Self::handle_data_event(evt);
355	                },
356	                else => {
357	                    log::debug!("AsyncRunner all channels closed, exiting");
358	                    return;
359	                }
360	            };
361	        }
362	    }
