370	    /// Handles a data command by sending to the `DataEngine`.
371	    #[inline]
372	    pub fn handle_data_command(cmd: DataCommand) {
373	        msgbus::send_data_command(MessagingSwitchboard::data_engine_execute(), cmd);
374	    }
