376	    /// Handles a data event by sending to the appropriate `DataEngine` endpoint.
377	    #[inline]
378	    pub fn handle_data_event(event: DataEvent) {
379	        match event {
380	            DataEvent::Data(data) => {
381	                msgbus::send_data(MessagingSwitchboard::data_engine_process_data(), data);
382	            }
383	            DataEvent::Instrument(data) => {
384	                msgbus::send_any(MessagingSwitchboard::data_engine_process(), &data);
385	            }
386	            DataEvent::Response(resp) => {
387	                msgbus::send_data_response(MessagingSwitchboard::data_engine_response(), resp);
388	            }
389	            DataEvent::FundingRate(funding_rate) => {
390	                msgbus::send_any(MessagingSwitchboard::data_engine_process(), &funding_rate);
391	            }
392	            DataEvent::InstrumentStatus(status) => {
393	                msgbus::send_any(MessagingSwitchboard::data_engine_process(), &status);
394	            }
395	            DataEvent::OptionGreeks(greeks) => {
396	                msgbus::send_any(MessagingSwitchboard::data_engine_process(), &greeks);
397	            }
398	            #[cfg(feature = "defi")]
399	            DataEvent::DeFi(data) => {
400	                msgbus::send_defi_data(MessagingSwitchboard::data_engine_process_defi_data(), data);
401	            }
402	        }
403	    }
404	
405	    /// Handles an execution command by sending to the `ExecEngine`.
406	    #[inline]
407	    pub fn handle_exec_command(cmd: TradingCommand) {
408	        msgbus::send_trading_command(MessagingSwitchboard::exec_engine_execute(), cmd);
409	    }
410	
411	    /// Handles an execution event by sending to the appropriate engine endpoint.
412	    #[inline]
413	    pub fn handle_exec_event(event: ExecutionEvent) {
414	        match event {
415	            ExecutionEvent::Order(order_event) => {
416	                msgbus::send_order_event(MessagingSwitchboard::exec_engine_process(), order_event);
417	            }
418	            ExecutionEvent::OrderSubmittedBatch(batch) => {
419	                for submitted in batch {
420	                    msgbus::send_order_event(
421	                        MessagingSwitchboard::exec_engine_process(),
422	                        OrderEventAny::Submitted(submitted),
423	                    );
424	                }
425	            }
426	            ExecutionEvent::OrderAcceptedBatch(batch) => {
427	                for accepted in batch {
428	                    msgbus::send_order_event(
429	                        MessagingSwitchboard::exec_engine_process(),
430	                        OrderEventAny::Accepted(accepted),
431	                    );
432	                }
433	            }
434	            ExecutionEvent::OrderCanceledBatch(batch) => {
435	                for canceled in batch {
436	                    msgbus::send_order_event(
437	                        MessagingSwitchboard::exec_engine_process(),
438	                        OrderEventAny::Canceled(canceled),
439	                    );
440	                }
441	            }
442	            ExecutionEvent::Report(report) => {
443	                Self::handle_exec_report(report);
444	            }
445	            ExecutionEvent::Account(ref account) => {
446	                msgbus::send_account_state(
447	                    MessagingSwitchboard::portfolio_update_account(),
448	                    account,
449	                );
450	            }
451	        }
452	    }
453	
454	    #[inline]
455	    pub fn handle_exec_report(report: ExecutionReport) {
456	        let endpoint = MessagingSwitchboard::exec_engine_reconcile_execution_report();
457	        msgbus::send_execution_report(endpoint, report);
458	    }
