85	impl<T: Actor> Deref for ActorRef<T> {
86	    type Target = T;
87	
88	    fn deref(&self) -> &Self::Target {
89	        // SAFETY: Type was verified at construction time.
90	        unsafe { &*(self.actor_rc.get() as *const T) }
91	    }
92	}
