94	impl<T: Actor> DerefMut for ActorRef<T> {
95	    fn deref_mut(&mut self) -> &mut Self::Target {
96	        // SAFETY: Type was verified at construction time.
97	        unsafe { &mut *self.actor_rc.get().cast::<T>() }
98	    }
99	}
